// ПИНЫ КНОПОК (ВХОДНЫЕ СИГНАЛЫ 5В с панели)
const int btnLight = 2;      // Подсветка (вкл/выкл)
const int btnVentOn = 4;     // Активация вентиляции (вкл/выкл)
const int btnSpeed1 = 9;     // Первая скорость
const int btnSpeed2 = 12;    // Вторая скорость

// ПИНЫ ДРАЙВЕРА L298N (ВЫХОДЫ)
const int enAPin = 5;        // Разрешение мотора A (постоянно HIGH)
const int in1Pin = 6;        // Управление скоростью 1
const int in2Pin = 7;        // Управление скоростью 2
const int in3Pin = 8;        // Управление подсветкой

// ПЕРЕМЕННЫЕ СОСТОЯНИЙ
bool lightState = false;     // Вкл/выкл подсветки
bool ventActive = false;     // Активен ли режим вентиляции
bool speed1State = false;    // Статус первой скорости
bool speed2State = false;    // Статус второй скорости

// ПЕРЕМЕННЫЕ ДЛЯ АНТИДРЕБЕЗГА
unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50;

void setup() {
  // Настройка пинов кнопок (вход с подтяжкой к GND, так как подаётся 5В)
  pinMode(btnLight, INPUT);
  pinMode(btnVentOn, INPUT);
  pinMode(btnSpeed1, INPUT);
  pinMode(btnSpeed2, INPUT);

  // Настройка пинов драйвера
  pinMode(enAPin, OUTPUT);
  pinMode(in1Pin, OUTPUT);
  pinMode(in2Pin, OUTPUT);
  pinMode(in3Pin, OUTPUT);

  // Включаем разрешение мотора (постоянно)
  digitalWrite(enAPin, HIGH);

  // Инициализация: всё выключено
  digitalWrite(in1Pin, LOW);
  digitalWrite(in2Pin, LOW);
  digitalWrite(in3Pin, LOW);
}

void loop() {
  // 1. ОБРАБОТКА КНОПКИ ПОДСВЕТКИ (пин 2)
  if (digitalRead(btnLight) == HIGH && millis() - lastDebounceTime > debounceDelay) {
    lastDebounceTime = millis();
    lightState = !lightState;
    digitalWrite(in3Pin, lightState ? HIGH : LOW);
    delay(200); // Маленькая задержка, чтобы кнопка не срабатывала несколько раз
  }

  // 2. ОБРАБОТКА КНОПКИ АКТИВАЦИИ ВЕНТИЛЯЦИИ (пин 4)
  if (digitalRead(btnVentOn) == HIGH && millis() - lastDebounceTime > debounceDelay) {
    lastDebounceTime = millis();
    ventActive = !ventActive;

    if (!ventActive) {
      // Если выключили вентиляцию - сбрасываем все скорости
      speed1State = false;
      speed2State = false;
      digitalWrite(in1Pin, LOW);
      digitalWrite(in2Pin, LOW);
    }
    delay(200);
  }

  // 3. ОБРАБОТКА КНОПКИ ПЕРВОЙ СКОРОСТИ (пин 9) - только если вентиляция активна
  if (ventActive && digitalRead(btnSpeed1) == HIGH && millis() - lastDebounceTime > debounceDelay) {
    lastDebounceTime = millis();
    speed1State = !speed1State;

    // Если включили первую скорость - выключаем вторую (приоритет первой)
    if (speed1State) {
      speed2State = false;
    }
    updateMotor();
    delay(200);
  }

  // 4. ОБРАБОТКА КНОПКИ ВТОРОЙ СКОРОСТИ (пин 12) - только если вентиляция активна
  if (ventActive && digitalRead(btnSpeed2) == HIGH && millis() - lastDebounceTime > debounceDelay) {
    lastDebounceTime = millis();
    speed2State = !speed2State;

    // Если включили вторую скорость - выключаем первую (приоритет второй)
    if (speed2State) {
      speed1State = false;
    }
    updateMotor();
    delay(200);
  }
}

// ФУНКЦИЯ ОБНОВЛЕНИЯ СОСТОЯНИЯ МОТОРА
void updateMotor() {
  if (!ventActive) {
    // Если вентиляция выключена - мотор стоит
    digitalWrite(in1Pin, LOW);
    digitalWrite(in2Pin, LOW);
    return;
  }

  if (speed1State) {
    // Первая скорость
    digitalWrite(in1Pin, HIGH);
    digitalWrite(in2Pin, LOW);
  } 
  else if (speed2State) {
    // Вторая скорость
    digitalWrite(in1Pin, LOW);
    digitalWrite(in2Pin, HIGH);
  } 
  else {
    // Вентиляция активна, но скорости выключены - мотор стоит
    digitalWrite(in1Pin, LOW);
    digitalWrite(in2Pin, LOW);
  }
}
